# Patches the android/ folder generated by `flutter create` for Mnara.
# Run once from the repo root AFTER `flutter create` (see README).
# Usage: powershell -ExecutionPolicy Bypass -File tools\android_setup.ps1

$ErrorActionPreference = 'Stop'
function Patch([string]$Path, [scriptblock]$Edit) {
    if (-not (Test-Path $Path)) { Write-Host "SKIP (not found): $Path"; return }
    $text = Get-Content $Path -Raw
    $new = & $Edit $text
    if ($new -ne $text) { Set-Content $Path $new -NoNewline; Write-Host "patched: $Path" }
    else { Write-Host "unchanged: $Path" }
}

# 1) minSdk 23 + google-services plugin in the app module
Patch 'android\app\build.gradle.kts' {
    param($t)
    $t = $t -replace 'minSdk\s*=\s*flutter\.minSdkVersion', 'minSdk = 23'
    if ($t -notmatch 'com\.google\.gms\.google-services') {
        $t = $t -replace '(id\("dev\.flutter\.flutter-gradle-plugin"\))', "`$1`n    id(`"com.google.gms.google-services`")"
    }
    $t
}

# 2) declare the plugin version in settings.gradle.kts
Patch 'android\settings.gradle.kts' {
    param($t)
    if ($t -notmatch 'com\.google\.gms\.google-services') {
        $t = $t -replace '(id\("com\.android\.application"\)[^\r\n]*)', "`$1`n    id(`"com.google.gms.google-services`") version `"4.4.2`" apply false"
    }
    $t
}

# 3) INTERNET permission and tel: package visibility
Patch 'android\app\src\main\AndroidManifest.xml' {
    param($t)
    if ($t -notmatch 'android.permission.INTERNET') {
        $t = $t -replace '(<manifest[^>]*>)', "`$1`n    <uses-permission android:name=`"android.permission.INTERNET`"/>"
    }
    if ($t -notmatch '<queries>') {
        $q = "    <queries>`n        <intent>`n            <action android:name=`"android.intent.action.DIAL`"/>`n            <data android:scheme=`"tel`"/>`n        </intent>`n    </queries>`n"
        $t = $t -replace '(<application)', ($q + '    $1')
    }
    $t
}

if (-not (Test-Path 'android\app\google-services.json')) {
    Write-Host ''
    Write-Host 'REMINDER: put google-services.json in android\app\ (see docs\FIREBASE_SETUP.md).'
}
